BEGIN;
CREATE OR REPLACE FUNCTION public.lf_operation_policy_snapshot_guard_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $g$ DECLARE r record; v_ok boolean; BEGIN IF OLD.manifest ? 'operation_policy_snapshots' AND (OLD.manifest->'operation_policy_snapshots') IS DISTINCT FROM (NEW.manifest->'operation_policy_snapshots') THEN RAISE EXCEPTION 'BLOCK_POLICY_SNAPSHOT_IMMUTABLE execution=% operation=%',NEW.execution_id,NEW.operation_code; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NOT (NEW.status='ABANDONED' AND OLD.status='IN_PROGRESS' AND NEW.manifest ? 'abandoned_reason') THEN IF NOT (NEW.manifest ? 'operation_policy_snapshots') THEN RAISE EXCEPTION 'BLOCK_OPERATION_POLICY_MISSING execution=% operation=%',NEW.execution_id,NEW.operation_code; END IF; FOR r IN SELECT key AS policy_role,value AS snapshot FROM jsonb_each(NEW.manifest->'operation_policy_snapshots') LOOP SELECT EXISTS(SELECT 1 FROM public.lf_policy_versions p WHERE p.policy_code=r.snapshot->>'policy_code' AND p.policy_version=r.snapshot->>'policy_version' AND p.policy_sha=r.snapshot->>'policy_sha' AND p.effective_at<=OLD.started_at AND (p.superseded_at IS NULL OR p.superseded_at>OLD.started_at)) INTO v_ok; IF NOT v_ok THEN RAISE EXCEPTION 'BLOCK_OPERATION_POLICY_START_SNAPSHOT_INVALID execution=% role=% policy=% version=%',NEW.execution_id,r.policy_role,r.snapshot->>'policy_code',r.snapshot->>'policy_version'; END IF; END LOOP; END IF; RETURN NEW; END $g$;
DO $ab$ DECLARE r record; BEGIN FOR r IN SELECT execution_id FROM public.lf_operation_execution WHERE status='IN_PROGRESS' LOOP PERFORM public.lf_execution_mark_abandoned_v1(r.execution_id,'SIN_AVANCE_24H_OWNER_20261115'); END LOOP; END $ab$;
COMMIT;
